import * as THREE from 'three';
import {clamp,angleLerp} from './math.js';
export class PlayerController{constructor(scene){this.root=new THREE.Group();scene.add(this.root);this.velocity=new THREE.Vector3();this.yaw=0;this.cameraYaw=0;this.cameraPitch=.18;this.inCar=false;this.car=null;this.health=100;this.damage=0;this.walkTime=0;this.tilt=0;this.lastMove=0;this.playerMesh=null;this.keys=new Set();this.cameraDistance=10.8;this.cameraLift=5.6;this.cameraInitialized=false}
 attach(person){this.person=person;this.root=person.root;this.yaw=person.root.rotation.y}
 enter(car){this.inCar=true;this.car=car;car.occupied=true;car.stolen=true;this.root.visible=false;this.root=car.root;this.yaw=car.root.rotation.y;this.velocity.set(0,0,0)}
 exit(){if(!this.car)return;const car=this.car;this.inCar=false;this.root= this.person.root;this.root.visible=true;const a=car.root.rotation.y;this.root.position.set(car.root.position.x+Math.cos(a)*2,0,car.root.position.z-Math.sin(a)*2);this.root.rotation.y=a;this.yaw=a;car.occupied=false;car.ai=null;this.car=null;this.velocity.set(0,0,0)}
 update(dt,keys,camera,city,colliders=[]){dt=Math.min(dt,.035);const f=(keys.has('KeyW')||keys.has('ArrowUp'))?1:0,b=(keys.has('KeyS')||keys.has('ArrowDown'))?1:0,l=(keys.has('KeyA')||keys.has('ArrowLeft'))?1:0,r=(keys.has('KeyD')||keys.has('ArrowRight'))?1:0;const inputF=f-b,inputS=r-l;const forward=new THREE.Vector3(-Math.sin(this.cameraYaw),0,-Math.cos(this.cameraYaw));const side=new THREE.Vector3(Math.cos(this.cameraYaw),0,-Math.sin(this.cameraYaw));
 if(this.inCar){let car=this.car;const accelerating=inputF;car.velocity=clamp(car.velocity+accelerating*15*dt,-8,31);car.velocity*=Math.pow(.983,dt*60);if(Math.abs(car.velocity)>.3)car.root.rotation.y=angleLerp(car.root.rotation.y,car.root.rotation.y-inputS*Math.sign(car.velocity)*Math.min(1.3,Math.abs(car.velocity)*.095)*dt,Math.min(1,dt*5));const a=car.root.rotation.y;car.root.position.x+=-Math.sin(a)*car.velocity*dt;car.root.position.z+=-Math.cos(a)*car.velocity*dt;car.root.position.x=clamp(car.root.position.x,-130,185);car.root.position.z=clamp(car.root.position.z,-150,150);for(const w of car.wheels)w.rotation.x+=car.velocity*dt*1.8;this.yaw=a;this.speed=car.velocity;this.tilt+=(inputS*.12-this.tilt)*dt*3
 }else{const run=keys.has('ShiftLeft')||keys.has('ShiftRight'),speed=run?9.4:5.2;const desired=forward.multiplyScalar(inputF).add(side.multiplyScalar(inputS));if(desired.lengthSq()>1)desired.normalize();this.velocity.x+=(desired.x*speed-this.velocity.x)*Math.min(1,dt*10);this.velocity.z+=(desired.z*speed-this.velocity.z)*Math.min(1,dt*10);this.root.position.x=clamp(this.root.position.x+this.velocity.x*dt,-130,182);this.root.position.z=clamp(this.root.position.z+this.velocity.z*dt,-155,155);if(desired.lengthSq()>.03)this.yaw=angleLerp(this.yaw,Math.atan2(-desired.x,-desired.z),Math.min(1,dt*10));this.root.rotation.y=this.yaw;this.walkTime+=dt*Math.hypot(this.velocity.x,this.velocity.z)*1.3;if(this.person){this.person.legs[0].rotation.x=Math.sin(this.walkTime)*.5;this.person.legs[1].rotation.x=-Math.sin(this.walkTime)*.5;this.person.arms[0].rotation.x=-Math.sin(this.walkTime)*.25;this.person.arms[1].rotation.x=Math.sin(this.walkTime)*.25}this.speed=0;this.tilt=0}
 const target=new THREE.Vector3(this.root.position.x, this.inCar?1.6:1.45,this.root.position.z);const dist=this.inCar?this.cameraDistance+1.2:this.cameraDistance;const lookDir=new THREE.Vector3(-Math.sin(this.cameraYaw)*Math.cos(this.cameraPitch),Math.sin(this.cameraPitch),-Math.cos(this.cameraYaw)*Math.cos(this.cameraPitch));const desiredCam=target.clone().sub(lookDir.multiplyScalar(dist));desiredCam.y+=this.cameraLift;if(!this.cameraInitialized){camera.position.copy(desiredCam);this.cameraInitialized=true}else camera.position.lerp(desiredCam,1-Math.exp(-dt*7));camera.lookAt(target.x,target.y+.7,target.z);return{forward:inputF,side:inputS,speed:this.speed,position:this.root.position}}
}
export function clampCarToRoad(car){const x=car.root.position.x,z=car.root.position.z;const nx=Math.round(x/44)*44,nz=Math.round(z/44)*44;if(Math.abs(x-nx)<6&&Math.abs(z-nz)>7)car.root.position.x=nx+Math.sign(x-nx)*5.6;if(Math.abs(z-nz)<6&&Math.abs(x-nx)>7)car.root.position.z=nz+Math.sign(z-nz)*5.6}
